test('intentional pursuit contact is not dodged as an obstruction',()=>{const{sim,nav}=makeCourse();sim.frogs[0].body.setTransform(Vec2(10,19),0);sim.frogs[1].body.setActive(true);sim.frogs[1].body.setTransform(Vec2(11,19),0);nav.setDestination({x:28,y:19});nav.chase(1);for(let i=0;i<90;i++){sim.setInput(0,nav.input(sim,0));sim.setInput(1,{x:-1,y:0,held:false});sim.step();}assert.equal(nav.stats.obstructions,0);});
test('Pogo bounce events cannot renew the same physical grapple indefinitely',()=>{for(const seed of[1,23,123]){const a=pogo(true,seed),b=pogo(false,seed);assert.ok(a.bounces>5);assert.ok(a.maxGrappleSeconds>=3);assert.ok(b.maxGrappleSeconds<1.8,JSON.stringify(b));assert.ok(b.stats.releases>0);assert.ok(b.meters>50);}});
test('ordinary productive grapple still attaches, swings, contracts and releases',()=>{const{sim,nav}=makeCourse(courses[4]);const r=traverse(sim,nav,1800);assert.ok(r.success,JSON.stringify(r));assert.ok(nav.stats.attachments&&nav.stats.swings&&nav.stats.releases);});
test('current arena climbs improve over exact approved controller fixtures',()=>{const a=climbs(true),b=climbs(),old=a.filter(r=>r.success).length,current=b.filter(r=>r.success).length;assert.equal(a.length,36);assert.ok(current>old,JSON.stringify({old,current}));for(const arena of['sunny-pond','bathhouse','canopy','toyshop'])assert.ok(b.some(r=>r.arena===arena&&r.success));const pond=b.filter(r=>r.arena==='sunny-pond'&&r.goal.y<5);assert.ok(pond.every(r=>r.success&&r.seconds<15));});
test('navigation excludes exterior boundary tops and includes the first launch approach cost',()=>{const{sim}=makeCourse();const g=navigationGraph(sim);assert.ok(g.surfaces.every(s=>s.a.y>=0));const f=sim.frogs[0],from=nearestSurface(g.surfaces,f.body.getPosition(),sim)!;assert.equal(route(sim,from,from,new Map(),f.body.getPosition()),undefined);});
test('AI changes preserve all human physics, current layouts, controls, modifiers, modes, networking and voting bytes',()=>{const m=JSON.parse(readFileSync('docs/bot-competitiveness-preservation.json','utf8')),hash=(v:any)=>createHash('sha256').update(v).digest('hex');assert.equal(m.baseline,'c0915a01076c44b2e5c035609f97382f06d04afe');assert.deepEqual(Object.keys(m.files).filter(p=>p.startsWith('server/')).sort(),['server/navigation/geometry.ts','server/navigation/navigator.ts','server/strategy/tactics.ts']);for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(hash(r.original),r.beforeSha256,p);assert.equal(hash(readFileSync(p)),r.afterSha256,p);if(p.startsWith('server/'))assert.doesNotMatch(readFileSync(p,'utf8'),/setTransform|setPosition|setLinearVelocity|applyLinearImpulse|applyForce|\.infect\(|\.launch\(|\.fire\(/);}for(const[p,h]of Object.entries(m.protected))assert.equal(hash(finalPodiumPreservedSource(p,true)),h,p);});

test('historical movement comparisons pin approved navigation instead of accidentally upgrading both opponents',()=>{const m=JSON.parse(readFileSync('docs/bot-b2r-preservation.json','utf8'));assert.equal(readFileSync('tests/fixtures/b1-navigator.ts','utf8'),m.files['server/navigation/navigator.ts'].original.replace("'./geometry'","'./b1-geometry'"));const c=JSON.parse(readFileSync('docs/bot-c-preservation.json','utf8'));assert.equal(readFileSync('tests/fixtures/b1-geometry.ts','utf8'),c.files['server/navigation/geometry.ts'].original);});

test('vertical routes traverse up, between elevated ledges, and back down through real inputs',()=>{for(const c of[{name:'upper-to-lower',platforms:[[20,20,40,1],[10,15,4,.5]],start:[10,14.265],goal:[15,19]},{name:'elevated-crossing',platforms:[[20,20,40,1],[10,15,6,.5],[19,11,6,.5]],start:[10,14.265],goal:[19,10.265]}]){const{sim,nav}=makeCourse(c);const result=traverse(sim,nav,1800);assert.ok(result.success,JSON.stringify({course:c.name,...result}));}});

