import {test} from 'node:test';import assert from 'node:assert/strict';import {mouseWorld,mouseDirection,MouseControls} from '../src/input/mouse';import {makeCourse,courses} from '../scripts/bot-b1-harness';import {capture,restore} from '../src/simulation/state';import {Simulation,type Input} from '../src/simulation/world';import {Vec2} from 'planck';import {applyChaos} from '../src/chaos/registry';import {Connection} from '../src/network/client';
test('mouse conversion uses offset CSS bounds and logical camera space, independent of backing DPR',()=>{for(const scale of[.4,1,1.8]){const rect={left:130,top:75,width:1200*scale,height:675*scale};const p=mouseWorld({x:130+330*scale,y:75+150*scale},rect,{width:1200,height:675},(x,y)=>({x:x+60,y:y+30}))!;assert.ok(Math.abs(p.x-13)<1e-10);assert.ok(Math.abs(p.y-6)<1e-10);}assert.equal(mouseWorld({x:1,y:1},{left:0,top:0,width:0,height:0},{width:1200,height:675},(x,y)=>({x,y})),undefined);});
test('all arbitrary headings stay continuous; a fixed cursor is recomputed from the moving frog',()=>{for(let i=0;i<73;i++){const a=i*2*Math.PI/73,aim=mouseDirection({x:10,y:8},{x:10+7*Math.cos(a),y:8+7*Math.sin(a)})!;assert.ok(Math.abs(aim.aimX-Math.cos(a))<1e-12);assert.ok(Math.abs(aim.aimY-Math.sin(a))<1e-12);}assert.notDeepEqual(mouseDirection({x:10,y:8},{x:20,y:5}),mouseDirection({x:12,y:6},{x:20,y:5}));assert.equal(mouseDirection({x:1,y:1},{x:1,y:1}),undefined);});
test('manual shots use aim independently of movement without changing jump strength or ground speed',()=>{const a=makeCourse(),b=makeCourse();for(let i=0;i<85;i++){const base={x:1,y:0,held:i>=20&&i<75};a.sim.setInput(0,base);b.sim.setInput(0,{...base,aimX:-.6,aimY:-.8});a.sim.step();b.sim.step();assert.deepEqual({...b.sim.frogs[0].body.getPosition()},{...a.sim.frogs[0].body.getPosition()});assert.deepEqual({...b.sim.frogs[0].body.getLinearVelocity()},{...a.sim.frogs[0].body.getLinearVelocity()});}});
test('airborne action aims freely while retaining ordinary firing, holding and detaching',()=>{const{sim}=makeCourse({...courses[0],start:[5,8]});const f=sim.frogs[0];for(const a of[.19,1.37,2.63,4.79,5.83]){sim.cancelAction(f);sim.setInput(0,{x:-1,y:0,held:false});sim.setInput(0,{x:-1,y:0,held:true,aimX:Math.cos(a),aimY:Math.sin(a)});sim.step();assert.ok(f.tongue);assert.ok(Math.abs(f.tongue!.direction.x-Math.cos(a))<1e-12);assert.ok(Math.abs(f.tongue!.direction.y-Math.sin(a))<1e-12);sim.setInput(0,{x:1,y:0,held:false});sim.step();assert.equal(f.tongue,undefined);}});
test('explicitly approved assist policy: normal mouse shots are manual; Magnet Mouths retains its effect',()=>{const{sim}=makeCourse({...courses[0],start:[4,10]});const other=sim.frogs[1];other.body.setActive(true);other.body.setTransform(Vec2(9,10.5),0);const f=sim.frogs[0];sim.fire(f,{x:0,y:0,held:true,aimX:1,aimY:0});assert.deepEqual(f.tongue!.direction,{x:1,y:0});assert.equal(f.aimAssistTarget,undefined);sim.fire(f,{x:1,y:0,held:true});assert.equal(f.aimAssistTarget,1);applyChaos(sim,['magnet_mouths']);sim.fire(f,{x:0,y:0,held:true,aimX:1,aimY:0});assert.equal(f.aimAssistTarget,1);assert.ok(f.tongue!.direction.y>0);});
test('snapshot capture/restore and buffered press direction retain the separate aim fields',()=>{const{sim}=makeCourse({...courses[0],start:[4,10]});sim.setInput(0,{x:1,y:0,held:true,aimX:.6,aimY:-.8});sim.step();const s=capture(sim),copy=new Simulation();restore(copy,s);assert.equal(copy.frogs[0].input.aimX,.6);assert.equal(copy.frogs[0].input.aimY,-.8);assert.deepEqual(copy.frogs[0].tongue!.direction,sim.frogs[0].tongue!.direction);});
class Surface{listeners=new Map<string,((e:any)=>void)[]>();addEventListener(type:string,fn:(e:any)=>void){this.listeners.set(type,[...(this.listeners.get(type)??[]),fn]);}emit(type:string,event:any={}){for(const fn of this.listeners.get(type)??[])fn({target:this,preventDefault(){},...event});}capture:number|null=null;setPointerCapture(id:number){this.capture=id;}hasPointerCapture(id:number){return this.capture===id;}releasePointerCapture(){this.capture=null;}}
function fixture(run:(m:MouseControls,canvas:Surface,w:Surface,setAllowed:(v:boolean)=>void)=>void){const old=(globalThis as any).window,w=new Surface(),canvas=new Surface();(globalThis as any).window=w;let allowed=true;try{const m=new MouseControls(canvas as any,()=>allowed,p=>p,()=>({x:0,y:0}),()=>{});run(m,canvas,w,v=>allowed=v);}finally{(globalThis as any).window=old;}}
const base:Input={x:1,y:0,held:false},down={pointerType:'mouse',pointerId:1,button:0,clientX:3,clientY:4};
test('mouse ownership, rapid clicks, outside release, cancellation and combined Space holds remain independent',()=>fixture((m,c,w)=>{for(let i=0;i<10;i++){c.emit('pointerdown',down);assert.equal(m.compose(base).held,true);w.emit('pointerup',{...down,target:w});assert.equal(m.compose(base).held,false);}c.emit('pointerdown',down);w.emit('pointercancel',{pointerId:99});assert.equal(m.held,true);w.emit('pointercancel',{pointerId:1});assert.equal(m.held,false);c.emit('pointerdown',down);assert.equal(m.compose({...base,held:true}).held,true);w.emit('pointerup',down);assert.equal(m.compose({...base,held:true}).held,true);assert.equal(m.compose(base).held,false);c.emit('pointerdown',down);c.emit('lostpointercapture',{pointerId:1});assert.equal(m.held,false);c.emit('pointerdown',down);m.reset();assert.equal(m.held,false);}));
test('keyboard aim can be selected explicitly; movement does not override stationary mouse aim',()=>fixture((m,c,w)=>{c.emit('pointerdown',down);w.emit('pointerup',down);const aim=m.compose(base);assert.equal(aim.aimX,.6);assert.equal(aim.aimY,.8);w.emit('keydown',{code:'KeyA'});assert.equal(m.compose({...base,x:-1}).aimX,.6);w.emit('keydown',{code:'KeyQ'});assert.equal(m.compose(base).aimX,undefined);w.emit('pointermove',{target:c,...down,clientX:4,clientY:3,buttons:0});assert.equal(m.compose(base).aimX,.8);}));
test('touch/pen, right-click and disabled/menu input never become mouse actions',()=>fixture((m,c,w,setAllowed)=>{for(const pointerType of['touch','pen'])c.emit('pointerdown',{...down,pointerType});assert.equal(m.held,false);c.emit('pointerdown',{...down,button:2});assert.equal(m.held,false);setAllowed(false);c.emit('pointerdown',down);assert.equal(m.held,false);w.emit('pointermove',{target:c,...down,buttons:0});assert.equal(m.active,false);}));
test('aim-only frame updates use normal periodic transport while action edges remain immediate',()=>{let sent=0;const stub={input:{x:0,y:0,held:false},sendInput(){sent++;}};Connection.prototype.setInput.call(stub as any,{x:0,y:0,held:false,aimX:.6,aimY:-.8},false);assert.equal(sent,0);Connection.prototype.setInput.call(stub as any,{x:0,y:0,held:true,aimX:.6,aimY:-.8});assert.equal(sent,1);Connection.prototype.setInput.call(stub as any,{x:0,y:0,held:true,aimX:.8,aimY:-.6});assert.equal(sent,2);});

test('all approved mobile, CPU, modifier, scoring and arena sources remain exact; physics is unchanged after aim selection',async()=>{const{readFileSync}=await import('node:fs'),{createHash}=await import('node:crypto'),hash=(v:any)=>createHash('sha256').update(v).digest('hex'),m=JSON.parse(readFileSync('docs/desktop-mouse-preservation.json','utf8'));for(const[p,h]of Object.entries(m.protected))assert.equal(hash(readFileSync(p)),h,p);for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(hash(r.original),r.beforeSha256,p);assert.equal(hash(readFileSync(p)),r.afterSha256,p);}const original=m.files['src/simulation/world.ts'].original,now=readFileSync('src/simulation/world.ts','utf8');assert.equal(now.slice(now.indexOf('  step()')),original.slice(original.indexOf('  step()')));assert.equal(now.slice(now.indexOf('  launch('),now.indexOf('  fire(')),original.slice(original.indexOf('  launch('),original.indexOf('  fire(')));});
